// Wrong: no label at all. TalkBack focuses it and says just "button".
IconButton(onClick = ::share) {
  Icon(Icons.Default.Share, contentDescription = null)
}

// Right: the description goes on the Icon. IconButton's clickable modifier
// merges its descendants, so the icon's label becomes the button's label.
IconButton(onClick = ::share) {
  Icon(Icons.Default.Share, contentDescription = stringResource(R.string.share))
}

// Decorative: the row's own text already says everything, so null is correct.
Row(Modifier.clickable(onClick = ::open)) {
  Icon(Icons.Default.Folder, contentDescription = null)
  Text(folder.name)
}

// Views. Wrong:
