// noHideDescendants removes the view AND everything under it — the right knob
// for the screen sitting behind a sheet you drew yourself.
binding.content.importantForAccessibility =
  View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS

