// A View exposes itself through a delegate — no subclassing required
ViewCompat.setAccessibilityDelegate(chartView, object : AccessibilityDelegateCompat() {
  override fun onInitializeAccessibilityNodeInfo(
    host: View,
    info: AccessibilityNodeInfoCompat,
  ) {
    super.onInitializeAccessibilityNodeInfo(host, info)
    info.contentDescription = "Weekly steps, 42,300"
    info.roleDescription = "chart"
  }
})

// Ten bars on one canvas are ONE node until you publish virtual ones
class ChartTouchHelper(private val view: ChartView) : ExploreByTouchHelper(view) {

  override fun getVirtualViewAt(x: Float, y: Float): Int =
    view.barIndexAt(x, y) ?: HOST_ID

  override fun getVisibleVirtualViews(ids: MutableList<Int>) {
    view.bars.indices.forEach(ids::add)
  }

  override fun onPopulateNodeForVirtualView(id: Int, node: AccessibilityNodeInfoCompat) {
    node.contentDescription = view.bars[id].label
    node.setBoundsInParent(view.boundsOf(id))   // required by ExploreByTouchHelper
    node.addAction(AccessibilityNodeInfoCompat.ACTION_CLICK)
  }

  override fun onPerformActionForVirtualView(id: Int, action: Int, args: Bundle?) =
    action == AccessibilityNodeInfoCompat.ACTION_CLICK && view.selectBar(id)
}

ViewCompat.setAccessibilityDelegate(chartView, ChartTouchHelper(chartView))

// RecyclerView already does this for rows; Compose does it for the whole screen
