  onDelete(item.id)
  true
}
ViewCompat.addAccessibilityAction(holder.itemView, getString(R.string.move_up)) { _, _ ->
  onMove(item.id, offset = -1)
  true
}

// Rename the default action instead of adding a second one that does the same
ViewCompat.replaceAccessibilityAction(
  holder.itemView,
  AccessibilityActionCompat.ACTION_CLICK,
  getString(R.string.open_article),
) { _, _ -> onOpen(item.id); true }

// Compose: on the row itself — the node the user actually lands on
@Composable
fun MessageRow(item: Message, onOpen: () -> Unit, onDelete: () -> Unit, onUp: () -> Unit) {
  val delete = stringResource(R.string.delete)
  val moveUp = stringResource(R.string.move_up)
  Row(
    Modifier
      .clickable(onClickLabel = stringResource(R.string.open_article), onClick = onOpen)
      .semantics {
        customActions = listOf(
          CustomAccessibilityAction(delete) { onDelete(); true },
          CustomAccessibilityAction(moveUp) { onUp(); true },
        )
      },
  ) { Text(item.subject) }
}

