// Reading order when the layout order and the visual order disagree.
// XML: <TextView android:id="@+id/price"
//                android:accessibilityTraversalBefore="@id/title" />
Column(Modifier.semantics { isTraversalGroup = true }) {
  Text(price, Modifier.semantics { traversalIndex = -1f })   // read first
  Text(title)
}

// Give focus back to the control that opened the sheet
