IconButton(onClick = ::open, modifier = Modifier.focusRequester(filterButton)) {
  Icon(Icons.Default.FilterList, contentDescription = stringResource(R.string.filters))
}
LaunchedEffect(sheetOpen) { if (!sheetOpen) filterButton.requestFocus() }

// Modifier order decides the target: padding AFTER clickable is inside it.
Icon(
  Icons.Default.Close,
  contentDescription = stringResource(R.string.close),
  modifier = Modifier.size(24.dp).clickable(onClick = onClose),      // 24dp target
)
Icon(
