// Views: grow the touch area without moving the icon. Note that the node bounds
// TalkBack highlights do NOT grow with it.
parent.post {
  val hit = Rect().also(icon::getHitRect)
  hit.inset(-12.dp.toPx(resources), -12.dp.toPx(resources))
  parent.touchDelegate = TouchDelegate(hit, icon)
}

// Contrast is measured against what is actually behind the pixel
val ratio = ColorUtils.calculateContrast(
  MaterialTheme.colorScheme.onSurfaceVariant.toArgb(),
  MaterialTheme.colorScheme.surface.toArgb(),
)
check(ratio >= 4.5)   // 3.0 is only for >=24sp text, icons and borders

// WRONG — text sized in dp, in a box that cannot grow
Row(Modifier.fillMaxWidth().height(56.dp)) {                  // clips at 200%
  Text(
    item.title,
    fontSize = with(LocalDensity.current) { 16.dp.toSp() },   // opts out of font scale
    maxLines = 1,
    overflow = TextOverflow.Ellipsis,
  )
}

// RIGHT — sp for text, a minimum instead of a height, room to wrap
Row(
  Modifier
    .fillMaxWidth()
    .heightIn(min = 56.dp)
    .padding(vertical = 8.dp),
  verticalAlignment = Alignment.CenterVertically,
) {
  Text(
    item.title,
    style = MaterialTheme.typography.bodyLarge,   // 16.sp — follows the user
    modifier = Modifier.weight(1f),
  )
  Text(item.price, style = MaterialTheme.typography.labelLarge)
}

// Non-linear scaling: never multiply by fontScale yourself on API 34+
