// View tests: one setup call turns ATF on for every Espresso interaction
@Before fun enableChecks() {
  AccessibilityChecks.enable()
    .setRunChecksFromRootView(true)              // the whole screen, not just the view
    .setSuppressingResultMatcher(                // carry one tracked failure
      matchesViews(withId(R.id.legacy_banner)),
    )
}

// Compose: the same rule set plus real assertions on the semantics tree
class CheckoutTest {
  @get:Rule val rule = createAndroidComposeRule<MainActivity>()

  @Before fun setUp() {
    rule.enableAccessibilityChecks()
  }

  @Test fun payButtonIsLabelledAndBigEnough() {
    rule.onNodeWithContentDescription("Pay 12.40 euros")
      .assert(hasClickAction())
      .assertHeightIsAtLeast(48.dp)
      .performClick()                            // checks run before the action

    rule.onNodeWithText("Order placed").assertIsDisplayed()
  }

  @Test fun paymentMethodExposesItsState() {
    rule.onNodeWithTag("payment")
      .assertContentDescriptionEquals("Payment method")
      .assert(
        SemanticsMatcher.expectValue(
          SemanticsProperties.StateDescription, "Card ending 4242",
        ),
      )
  }
}

