// The user's ordered preference list, not a single locale (API 24+)
val prefs: LocaleList = resources.configuration.locales   // e.g. [uk-UA, ru-RU]
val resolved: Locale = prefs[0]

// Resolution, one user entry at a time:
//   uk-UA -> uk : no values-uk anywhere      -> keep going
//   ru-RU -> ru : values-ru exists           -> match, stop
// values/ wins only when NO entry in the list matched anything.
// Since API 24 a near miss counts too: fr-CH finds values-fr-rFR,
// where API 23 would have dropped straight to the default.

// Compose reads the same configuration
@Composable fun currentLocale(): Locale = LocalConfiguration.current.locales[0]

// Ship fewer locales on purpose (AGP 8.10+; was resourceConfigurations)
android {
  androidResources {
    localeFilters += listOf("en", "ru", "de")   // strips AppCompat's locales as well
  }
}

// WRONG — captured once, stale after a per-app language change
private val formatter = NumberFormat.getInstance(Locale.getDefault())

// RIGHT — read the configuration where you format
fun format(value: Long, res: Resources): String =
  NumberFormat.getInstance(res.configuration.locales[0]).format(value)

// res/xml/locales_config.xml
// <locale-config xmlns:android="http://schemas.android.com/apk/res/android">
//   <locale android:name="en"/>
//   <locale android:name="ru"/>
//   <locale android:name="de"/>
// </locale-config>
//
// AndroidManifest: <application android:localeConfig="@xml/locales_config">
// or let AGP generate it: androidResources { generateLocaleConfig = true }

// One call, every API level. 33+ hands it to LocaleManager and recreates the
// activities; below 33 AppCompat stores and re-applies it itself.
fun setLanguage(tag: String?) {
  AppCompatDelegate.setApplicationLocales(
    if (tag == null) LocaleListCompat.getEmptyLocaleList()   // "follow the system"
    else LocaleListCompat.forLanguageTags(tag),
  )
}

// Read the explicit choice back — not Locale.getDefault()
val chosen = AppCompatDelegate.getApplicationLocales()       // empty == system
val selectedRow = chosen.toLanguageTags().ifEmpty { SYSTEM_ROW }

// The language may not even be installed: App Bundles split by language
fun switchTo(context: Context, tag: String, onReady: () -> Unit) {
  val manager = SplitInstallManagerFactory.create(context)
  val locale = Locale.forLanguageTag(tag)
  if (locale.language in manager.installedLanguages) return onReady()

  manager.startInstall(
    SplitInstallRequest.newBuilder().addLanguage(locale).build(),
  ).addOnSuccessListener { onReady() }
}

// Push text is built on the server, so the server needs to know
suspend fun syncLocale(api: Api) =
  api.updateProfile(locale = AppCompatDelegate.getApplicationLocales().toLanguageTags())

