// Prove it before the translations arrive:
//   buildTypes { debug { isPseudoLocalesEnabled = true } }   -> run the app in ar-XB
//   adb shell settings put global debug.force_rtl 1

// build.gradle.kts
android {
  buildTypes {
    debug {
      isPseudoLocalesEnabled = true    // adds en-XA and ar-XB to the device language list
    }
  }
  androidResources { generateLocaleConfig = true }

  lint {
    abortOnError = true
    error += listOf(
      "HardcodedText",        // a string that never reached strings.xml
      "StringFormatInvalid",
      "StringFormatMatches",  // a translation that dropped or retyped %1$s
      "ImpliedQuantity",      // a plural ru and ar will need more categories for
      "MissingTranslation",   // turn on once the first locale has landed
    )
  }
}

